CREATE TABLE targets (city TEXT PRIMARY KEY, avg_fare_usd REAL NOT NULL);
INSERT INTO targets VALUES ('Austin', 1.5), ('Berlin', 2.5), ('Lisbon', 2.0), ('Osaka', 2.25);
SELECT g.city, g.avg_fare_usd AS target, round(avg(t.fare_usd), 2) AS actual,
       round(avg(t.fare_usd) - g.avg_fare_usd, 2) AS gap
FROM targets AS g
JOIN trip_facts AS t ON t.city = g.city
GROUP BY g.city
ORDER BY gap DESC;
